#include <errno.h>
#include <string.h>
#include <sys/stat.h>
#include "test_env.h"

/*
 * Test driver for JpegCompressor (Linux only, uses stdio and files).
 * Scenarios run one after the other: a scenario uploads its generated image
 * and calls start_compression; the next trigger after compression_completed
 * checks the result, downloads the compressed data, saves it as
 * test_output/<name>.j2k (with the raw image in <name>.raw, for an external
 * comparison) and starts the next scenario.
 * After every compression, successful or not, it also checks that OpenJPEG
 * freed all its memory and that the encoder memory pool is empty.
 * For each compression it also prints the encoder pool fragmentation: the
 * pool high-water mark (pool size really needed) compared with the peak of
 * memory in use; the worst case is printed at the end.
 * Failures are printed; when all scenarios are done the process exits with
 * the number of failures as exit code.
 */

// extern jpeg library functions, for memory check only
extern size_t jpegcompressor_get_memory_leaked(void);
extern size_t jpegcompressor_get_memory_high_water(void);
extern size_t opj_mem_pool_get_used(void);

#define MAX_IMAGE_SIZE (1024U * 1024U)

typedef enum { PATTERN_SMOOTH, PATTERN_NOISE } pattern_t;

typedef struct {
   const char *name;
   asn1SccJpeg_Compression_Config config;
   pattern_t pattern;
   unsigned upload_size;   // 0: whole image, otherwise number of bytes uploaded
   asn1SccJpeg_Result_Code expected;
} scenario_t;

#define CONFIG(w, h, nc, depth, ratio, res, tile) \
   { (w), (h), (nc), (depth), 0, (ratio), (res), (tile) }
#define SIGNED_CONFIG(w, h, nc, depth, ratio, res, tile) \
   { (w), (h), (nc), (depth), 1, (ratio), (res), (tile) }

static const scenario_t scenarios[] = {
   { "gray8_lossless_tiled",   CONFIG(256, 256, 1, 8, 0, 6, 64),  PATTERN_SMOOTH, 0, Jpeg_Result_Code_ok },
   { "gray8_signed_lossless",  SIGNED_CONFIG(128, 128, 1, 8, 0, 5, 64), PATTERN_SMOOTH, 0, Jpeg_Result_Code_ok },
   { "rgb8_lossless_edge_tiles", CONFIG(200, 150, 3, 8, 0, 5, 64),     PATTERN_SMOOTH, 0, Jpeg_Result_Code_ok },
   { "gray12_lossless_single", CONFIG(128, 128, 1, 12, 0, 6, 0),  PATTERN_SMOOTH, 0, Jpeg_Result_Code_ok },
   { "rgb8_lossy10_single",    CONFIG(256, 256, 3, 8, 10, 6, 0),        PATTERN_SMOOTH, 0, Jpeg_Result_Code_ok },
   { "gray16_lossy20_tiled",   CONFIG(300, 200, 1, 16, 20, 4, 128), PATTERN_SMOOTH, 0, Jpeg_Result_Code_ok },
   { "err_partial_upload",     CONFIG(256, 256, 1, 8, 0, 6, 64),  PATTERN_SMOOTH, 1000, Jpeg_Result_Code_input_size_mismatch },
   { "err_too_many_levels",    CONFIG(256, 256, 1, 8, 0, 8, 64),  PATTERN_SMOOTH, 0, Jpeg_Result_Code_invalid_config },
   { "rgb8_large_edge_tiles",  CONFIG(384, 384, 3, 8, 0, 6, 256), PATTERN_SMOOTH, 0, Jpeg_Result_Code_ok },
   { "err_output_overflow",    CONFIG(1024, 1024, 1, 8, 0, 6, 256), PATTERN_NOISE, 0, Jpeg_Result_Code_output_overflow },
   { "err_out_of_memory",      CONFIG(1024, 1024, 1, 8, 0, 6, 0), PATTERN_SMOOTH, 0, Jpeg_Result_Code_out_of_memory },
   { "gray8_after_errors",     CONFIG(256, 256, 1, 8, 0, 6, 64),  PATTERN_SMOOTH, 0, Jpeg_Result_Code_ok },
};
#define SCENARIO_COUNT (sizeof(scenarios) / sizeof(scenarios[0]))

static unsigned char image[MAX_IMAGE_SIZE];
static unsigned char compressed[MAX_IMAGE_SIZE];

static unsigned current;
static int waiting;
static int completed;
static asn1SccJpeg_Compression_Result completion;
static int failures;
// Worst pool fragmentation over the scenarios: memory lost, in % of the peak
static double worst_fragmentation;
static const char *worst_fragmentation_name = "none";

static void fail(const char *what)
{
   printf("[test_env] FAIL %s: %s\n", scenarios[current].name, what);
   failures++;
}

static unsigned image_size(const asn1SccJpeg_Compression_Config *c)
{
   return (unsigned)(c->width * c->height * c->num_components * (c->bit_depth <= 8 ? 1 : 2));
}

static void generate_image(const scenario_t *s)
{
   const asn1SccJpeg_Compression_Config *c = &s->config;
   unsigned bytes = c->bit_depth <= 8 ? 1U : 2U;
   unsigned max = (1U << c->bit_depth) - 1U;
   unsigned seed = 12345U;
   unsigned i = 0;
   unsigned comp, x, y;

   for (comp = 0; comp < c->num_components; comp++) {
      for (y = 0; y < c->height; y++) {
         for (x = 0; x < c->width; x++) {
            unsigned v;
            seed ^= seed << 13; // xorshift32
            seed ^= seed >> 17;
            seed ^= seed << 5;
            if (s->pattern == PATTERN_NOISE) {
               v = (seed >> 16) & max;
            } else {
               v = ((x * 7U + y * 3U + comp * 80U) * (max + 1U) / 1024U + ((seed >> 16) & 3U)) & max;
            }
            image[i++] = (unsigned char)(v & 0xFFU);
            if (bytes == 2U) {
               image[i++] = (unsigned char)(v >> 8);
            }
         }
      }
   }
}

static void save(const char *name, const char *extension, const unsigned char *data, unsigned size)
{
   char path[128];
   FILE *f;

   snprintf(path, sizeof(path), "test_output/%s.%s", name, extension);
   f = fopen(path, "wb");
   if (f == NULL) {
      printf("[test_env] cannot open %s: %s\n", path, strerror(errno));
      fail("cannot write output file");
      return;
   }
   if (fwrite(data, 1, size, f) != size) {
      fail("cannot write output file");
   }
   fclose(f);
}

static void upload(asn1SccJpeg_Write_Request *request, unsigned offset, unsigned size,
                   asn1SccJpeg_Result_Code *result)
{
   unsigned length = size - offset < sizeof(request->data.arr) ? size - offset
                                                               : (unsigned)sizeof(request->data.arr);
   request->offset = offset;
   request->data.nCount = (int)length;
   memcpy(request->data.arr, image + offset, length);
   test_env_RI_write_buffer(request, result);
}

// Returns 1 when the compression was started, 0 if the scenario failed before
static int start_scenario(const scenario_t *s)
{
   asn1SccJpeg_Result_Code result;
   asn1SccJpeg_Write_Request request;
   asn1SccJpeg_Read_Request read_request = { 0, 16 };
   asn1SccJpeg_Data_Chunk chunk;
   unsigned size = s->upload_size ? s->upload_size : image_size(&s->config);
   unsigned offset;

   if (image_size(&s->config) > MAX_IMAGE_SIZE) {
      fail("image larger than the test buffer");
      return 0;
   }
   generate_image(s);
   test_env_RI_clear_buffer(&result);
   if (result != Jpeg_Result_Code_ok) {
      fail("clear_buffer");
   }
   // Nothing to read after a clear
   test_env_RI_read_buffer(&read_request, &chunk, &result);
   if (result != Jpeg_Result_Code_no_output || chunk.nCount != 0) {
      fail("read_buffer after clear should return no-output");
   }
   // A chunk leaving a gap must be refused
   if (size > sizeof(request.data.arr)) {
      upload(&request, (unsigned)sizeof(request.data.arr), size, &result);
      if (result != Jpeg_Result_Code_invalid_offset) {
         fail("write_buffer leaving a gap should return invalid-offset");
      }
   }
   // Upload in order, re-sending the first chunk once (retransmission)
   for (offset = 0; offset < size; offset += sizeof(request.data.arr)) {
      upload(&request, offset, size, &result);
      if (result == Jpeg_Result_Code_ok && offset == sizeof(request.data.arr)) {
         upload(&request, 0, size, &result);
      }
      if (result != Jpeg_Result_Code_ok) {
         fail("write_buffer");
         return 0;
      }
   }
   waiting = 1;
   completed = 0;
   test_env_RI_start_compression(&s->config);
   return 1;
}

static void finish_scenario(const scenario_t *s)
{
   asn1SccJpeg_Compressor_Status status;
   asn1SccJpeg_Read_Request request;
   asn1SccJpeg_Data_Chunk chunk;
   asn1SccJpeg_Result_Code result;
   unsigned offset = 0;
   unsigned raw = image_size(&s->config);

   test_env_RI_status(&status);
   // Fragmentation: pool size really needed (high-water) beyond the peak in use
   const size_t high_water = jpegcompressor_get_memory_high_water();
   const double fragmentation = (status.memory_peak > 0U)
      ? 100.0 * ((double)high_water - (double)status.memory_peak) / (double)status.memory_peak
      : 0.0;
   if (fragmentation > worst_fragmentation) {
      worst_fragmentation = fragmentation;
      worst_fragmentation_name = s->name;
   }
   printf("[test_env] %-26s result=%d (expected %d) size=%7u/%7u B  pool peak=%8llu B"
          "  high-water=%8zu B (+%.1f%%)\n",
          s->name, (int)completion.result, (int)s->expected, (unsigned)completion.output_size, raw,
          (unsigned long long)status.memory_peak, high_water, fragmentation);

   if (jpegcompressor_get_memory_leaked() != 0U) {
      fail("OpenJPEG did not free all its memory (memory leak)");
   }
   if (opj_mem_pool_get_used() != 0U) {
      fail("encoder memory pool not empty after the compression");
   }
   if (completion.result != s->expected) {
      fail("unexpected compression result");
      return;
   }
   if (status.last_result != completion.result ||
       status.state != (s->expected == Jpeg_Result_Code_ok ? Jpeg_Compressor_State_completed
                                                            : Jpeg_Compressor_State_failed)) {
      fail("status does not match the completion");
   }
   if (s->expected != Jpeg_Result_Code_ok) {
      return;
   }
   // Download in 1000-byte requests (not a multiple of the 1024-byte chunk)
   // to exercise partial chunks
   do {
      request.offset = offset;
      request.length = 1000;
      test_env_RI_read_buffer(&request, &chunk, &result);
      if (result != Jpeg_Result_Code_ok) {
         fail("read_buffer");
         return;
      }
      memcpy(compressed + offset, chunk.arr, (size_t)chunk.nCount);
      offset += (unsigned)chunk.nCount;
   } while (chunk.nCount > 0);

   if (offset != completion.output_size || offset != status.output_size) {
      fail("downloaded size mismatch");
   }
   request.offset = offset + 1U;
   test_env_RI_read_buffer(&request, &chunk, &result);
   if (result != Jpeg_Result_Code_invalid_offset) {
      fail("read past the end should return invalid-offset");
   }
   save(s->name, "j2k", compressed, offset);
   save(s->name, "raw", image, raw);
}

void test_env_startup(void)
{
   current = 0;
   waiting = 0;
   failures = 0;
   // Output files go to test_output/ in the current working directory
   if (mkdir("test_output", 0755) != 0 && errno != EEXIST) {
      printf("[test_env] cannot create test_output/: %s\n", strerror(errno));
   }
}

void test_env_PI_compression_completed( const asn1SccJpeg_Compression_Result *IN_result )
{
   completion = *IN_result;
   completed = 1;
}


void test_env_PI_trigger( void )
{
   while (current < SCENARIO_COUNT) {
      if (waiting) {
         if (!completed) {
            return;
         }
         waiting = 0;
         finish_scenario(&scenarios[current]);
         current++;
      } else if (start_scenario(&scenarios[current])) {
         return; // wait for compression_completed
      } else {
         current++; // could not start, failure already counted
      }
   }
   printf("[test_env] worst pool fragmentation: +%.1f%% (%s)\n", worst_fragmentation,
          worst_fragmentation_name);
   printf("[test_env] %u scenarios, %d failure(s)\n", (unsigned)SCENARIO_COUNT, failures);
   fflush(stdout);
   _Exit(failures); // not exit(): it hangs in the TASTE runtime (observed on Linux)
}
